CREATE TABLE visits(id TEXT PRIMARY KEY,token_hash TEXT NOT NULL UNIQUE,csrf TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('Operator','Reviewer')),expires INTEGER NOT NULL,created INTEGER NOT NULL,writes INTEGER NOT NULL DEFAULT 0);
CREATE TABLE customers(id INTEGER PRIMARY KEY,tenant TEXT NOT NULL REFERENCES visits(id) ON DELETE CASCADE,company TEXT NOT NULL,segment TEXT NOT NULL,stage TEXT NOT NULL CHECK(stage IN ('LEAD','QUALIFIED','CUSTOMER')),UNIQUE(tenant,id));
CREATE TABLE contacts(id INTEGER PRIMARY KEY,tenant TEXT NOT NULL REFERENCES visits(id) ON DELETE CASCADE,customer_id INTEGER NOT NULL,name TEXT NOT NULL,email TEXT NOT NULL,preference TEXT NOT NULL CHECK(preference IN ('OK','UNSUBSCRIBED','REJECTED','HARD_BOUNCE','BLOCKED','CONTACTED')),FOREIGN KEY(tenant,customer_id) REFERENCES customers(tenant,id),UNIQUE(tenant,id));
CREATE TABLE activities(id INTEGER PRIMARY KEY,tenant TEXT NOT NULL REFERENCES visits(id) ON DELETE CASCADE,customer_id INTEGER NOT NULL,message TEXT NOT NULL,at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(tenant,customer_id) REFERENCES customers(tenant,id));
CREATE TABLE products(id INTEGER PRIMARY KEY,tenant TEXT NOT NULL REFERENCES visits(id) ON DELETE CASCADE,sku TEXT NOT NULL COLLATE NOCASE,name TEXT NOT NULL,category TEXT NOT NULL,description TEXT NOT NULL,UNIQUE(tenant,sku),UNIQUE(tenant,id));
CREATE TABLE prices(id INTEGER PRIMARY KEY,tenant TEXT NOT NULL REFERENCES visits(id) ON DELETE CASCADE,product_id INTEGER NOT NULL,version INTEGER NOT NULL,unit_price TEXT NOT NULL,currency TEXT NOT NULL CHECK(currency='USD'),source TEXT NOT NULL,at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(tenant,product_id) REFERENCES products(tenant,id),UNIQUE(tenant,product_id,version),UNIQUE(tenant,id));
CREATE TABLE quotes(id INTEGER PRIMARY KEY,tenant TEXT NOT NULL REFERENCES visits(id) ON DELETE CASCADE,customer_id INTEGER NOT NULL,label TEXT NOT NULL,at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(tenant,customer_id) REFERENCES customers(tenant,id),UNIQUE(tenant,id));
CREATE TABLE quote_versions(id INTEGER PRIMARY KEY,tenant TEXT NOT NULL REFERENCES visits(id) ON DELETE CASCADE,quote_id INTEGER NOT NULL,version INTEGER NOT NULL,product_id INTEGER NOT NULL,price_id INTEGER NOT NULL,snapshot TEXT NOT NULL,quantity TEXT NOT NULL,unit_price TEXT NOT NULL,subtotal TEXT NOT NULL,tax TEXT NOT NULL,total TEXT NOT NULL,currency TEXT NOT NULL CHECK(currency='USD'),status TEXT NOT NULL CHECK(status IN ('DRAFT','APPROVED')),at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(tenant,quote_id) REFERENCES quotes(tenant,id),FOREIGN KEY(tenant,product_id) REFERENCES products(tenant,id),FOREIGN KEY(tenant,price_id) REFERENCES prices(tenant,id),UNIQUE(tenant,quote_id,version),UNIQUE(tenant,id));
CREATE TABLE workflows(id INTEGER PRIMARY KEY,tenant TEXT NOT NULL REFERENCES visits(id) ON DELETE CASCADE,name TEXT NOT NULL,status TEXT NOT NULL,source_hash TEXT,at TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(tenant,source_hash),UNIQUE(tenant,id));
CREATE TABLE workflow_steps(id INTEGER PRIMARY KEY,tenant TEXT NOT NULL REFERENCES visits(id) ON DELETE CASCADE,workflow_id INTEGER NOT NULL,position INTEGER NOT NULL,agent TEXT NOT NULL,status TEXT NOT NULL,detail TEXT NOT NULL,at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(tenant,workflow_id) REFERENCES workflows(tenant,id),UNIQUE(tenant,workflow_id,position));
CREATE TABLE imports(id INTEGER PRIMARY KEY,tenant TEXT NOT NULL REFERENCES visits(id) ON DELETE CASCADE,digest TEXT NOT NULL,filename TEXT NOT NULL,csv_text TEXT NOT NULL,status TEXT NOT NULL,errors TEXT NOT NULL,workflow_id INTEGER NOT NULL,at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(tenant,workflow_id) REFERENCES workflows(tenant,id),UNIQUE(tenant,digest));
CREATE TABLE campaigns(id INTEGER PRIMARY KEY,tenant TEXT NOT NULL REFERENCES visits(id) ON DELETE CASCADE,name TEXT NOT NULL,segment TEXT NOT NULL,subject TEXT NOT NULL,body TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,status TEXT NOT NULL CHECK(status IN ('DRAFT','APPROVED','SIMULATED')),quote_version_id INTEGER,workflow_id INTEGER NOT NULL,at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(tenant,quote_version_id) REFERENCES quote_versions(tenant,id),FOREIGN KEY(tenant,workflow_id) REFERENCES workflows(tenant,id),UNIQUE(tenant,id));
CREATE TABLE recipients(id INTEGER PRIMARY KEY,tenant TEXT NOT NULL REFERENCES visits(id) ON DELETE CASCADE,campaign_id INTEGER NOT NULL,revision INTEGER NOT NULL,contact_id INTEGER NOT NULL,included INTEGER NOT NULL CHECK(included IN (0,1)),reason TEXT NOT NULL,FOREIGN KEY(tenant,campaign_id) REFERENCES campaigns(tenant,id),FOREIGN KEY(tenant,contact_id) REFERENCES contacts(tenant,id));
CREATE TABLE approvals(id INTEGER PRIMARY KEY,tenant TEXT NOT NULL REFERENCES visits(id) ON DELETE CASCADE,kind TEXT NOT NULL,object_id INTEGER NOT NULL,version INTEGER NOT NULL,content_hash TEXT NOT NULL,actor TEXT NOT NULL,result TEXT NOT NULL CHECK(result='APPROVED'),at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE executions(id INTEGER PRIMARY KEY,tenant TEXT NOT NULL REFERENCES visits(id) ON DELETE CASCADE,campaign_id INTEGER NOT NULL,revision INTEGER NOT NULL,status TEXT NOT NULL CHECK(status='SIMULATED'),at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(tenant,campaign_id) REFERENCES campaigns(tenant,id),UNIQUE(tenant,campaign_id,revision),UNIQUE(tenant,id));
CREATE TABLE results(id INTEGER PRIMARY KEY,tenant TEXT NOT NULL REFERENCES visits(id) ON DELETE CASCADE,execution_id INTEGER NOT NULL,contact_id INTEGER NOT NULL,delivered INTEGER NOT NULL,opened INTEGER NOT NULL,clicked INTEGER NOT NULL,FOREIGN KEY(tenant,execution_id) REFERENCES executions(tenant,id),FOREIGN KEY(tenant,contact_id) REFERENCES contacts(tenant,id));
CREATE INDEX contact_scope ON contacts(tenant,email);
CREATE TRIGGER immutable_price BEFORE UPDATE ON prices BEGIN SELECT RAISE(ABORT,'Price snapshots are immutable'); END;
CREATE TRIGGER immutable_quote BEFORE UPDATE OF snapshot,quantity,unit_price,subtotal,tax,total,product_id,price_id,quote_id,version,currency ON quote_versions BEGIN SELECT RAISE(ABORT,'Create a new quotation version'); END;
CREATE TRIGGER immutable_approval BEFORE UPDATE ON approvals BEGIN SELECT RAISE(ABORT,'Approval history is immutable'); END;
